  category: Category;
  text: string;
  choices: string;
  correct: string;
}
export interface QuizState {
  readonly index: number;
  readonly score: number;
  readonly answered: boolean;
}
export type LoadResult =
  | { kind: 'ready'; questions: readonly Question[] }
  | { kind: 'invalid' }
  | { kind: 'failed'; message: string };

